idx >= 0 ? t.substring(Math.max(0,idx-100), idx+200) : 'no "Data source" text; first 500 chars of main: ' + (document.querySelector('main')?.innerText || '').substring(0,500)

// Look for the panel editor pane elements
let pane = document.querySelector('[data-testid="panel-editor"]') || document.querySelector('.panel-editor') || document.querySelector('[class*="panelEditor"]');
pane ? pane.innerText.substring(0, 800) : 'no panel editor pane found; body length=' + document.body.innerText.length

// Look for the panel editor pane now
let pane = document.querySelector('[data-testid="panel-editor"]') || document.querySelector('.panel-editor') || document.querySelector('[class*="panelEditor"]') || document.querySelector('[class*="drawer"]');
pane ? pane.innerText.substring(0, 1000) : 'no pane; body=' + document.body.innerText.substring(0, 300)

// Scroll down the visualization picker to find Text panel
let picker = document.querySelector('[role="dialog"]') || document.querySelector('[class*="vis-picker"]') || document.querySelector('[class*="Visualization"]');
if (picker) picker.scrollTop = 400;
else document.querySelectorAll('button, div[role="button"]').forEach(el => {
  if (el.textContent.includes('Text')) el.scrollIntoView();
});
"scrolled"

// Find vis picker items
let items = document.querySelectorAll('[role="dialog"] button, [role="dialog"] [role="radio"], [role="dialog"] [role="option"], [class*="vis-item"], [class*="option"]');
let texts = Array.from(items).map(el => el.textContent.trim().substring(0,40)).filter(t => t);
texts.length > 0 ? texts.join('\n') : 'No items found; looking for vis-picker... ' + (document.querySelector('[class*="vis-picker"]') ? 'found vis-picker' : 'no vis-picker')

// Find the current visualization type displayed in the panel editor
let els = document.querySelectorAll('[class*="vis"], [class*="button"]');
let matches = Array.from(els).filter(el => el.textContent.match(/Stat|Text|Graph|Visualization|Change|current/i));
matches.map(el => el.textContent.trim().substring(0,60) + ' [' + el.className.substring(0,100) + ']').join('\n')

// Look for the current visualization button or the vis picker button
let allButtons = Array.from(document.querySelectorAll('button'));
let visButtons = allButtons.filter(b => b.textContent.includes('Stat') || b.textContent.includes('Text') || b.textContent.includes('Visualization') || b.className.includes('vis') || b.className.includes('current'));
visButtons.map(b => b.textContent.trim().substring(0,60) + ' cls=' + b.className.substring(0,60)).join('\n')

// Find the visualization switcher button - it should be near the top of the editor side panel
let allText = document.body.innerText;
let idx = allText.indexOf('Stat');
if (idx >= 0) console.log('Stat found at', idx);
idx = allText.indexOf('Text');
if (idx >= 0) console.log('Text found at', idx);
// Look for the current visualization picker area
let sidebar = document.querySelector('[class*="panel-editor"]') || document.querySelector('[class*="editor"]');
"Stat index: " + allText.indexOf('Stat') + ', Text index: ' + allText.indexOf('Text')

// Find the Text visualization button coordinates by scanning the DOM
let allEls = document.querySelectorAll('*');
let textEl = Array.from(allEls).find(el => el.textContent.trim() === 'Text' && el.offsetParent !== null && (el.tagName === 'BUTTON' || el.getAttribute('role') === 'button' || el.getAttribute('role') === 'radio' || el.tagName === 'DIV' && el.closest('[role="dialog"]')));
textEl ? textEl.tagName + ' ' + textEl.className + ' ' + textEl.getAttribute('role') : 'looking for text element...'

// Find all visible elements containing just "Text"
let walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT, null, false);
let nodes = [];
while(walker.nextNode()) {
  let t = walker.currentNode.textContent.trim();
  if (t === 'Text' && walker.currentNode.offsetParent !== null) {
    nodes.push(walker.currentNode.parentElement.tagName + ' cls=' + walker.currentNode.parentElement.className.substring(0,60));
  }
}
nodes.join(' | ')

// Find the tags section in settings
let tags = Array.from(document.querySelectorAll('[class*="tag"]')).map(el => el.textContent.trim()).filter(t => t);
tags.length > 0 ? tags.join(', ') : 'no tags found'

// Look for the tag elements in settings
let tagEls = document.querySelectorAll('[class*="Tag"]');
Array.from(tagEls).map(el => el.textContent.trim() + ' ' + el.className).join(' | ')

