// Try to find menu buttons that might have appeared
let btns = Array.from(document.querySelectorAll('button')).filter(b => b.offsetParent !== null && ['Edit','View','Explore','More...'].includes(b.textContent.trim()));
btns.map(b => b.textContent.trim() + ' [' + (b.getAttribute('aria-label')||'') + ']').join(' | ')

// Check the panel header for menu buttons
let panelRegion = document.querySelector('[aria-label="rpgr3-r1 Availability"]') || document.querySelector('region') || document.querySelector('[aria-label*="rpgr3-r1"]');
if (!panelRegion) panelRegion = document.querySelectorAll('section, [role="region"]');
